def standardize_city(value):
  value = value.lower() # Convert the string to lowercase
  if re.search(r'honolulu', value) or re.search(r'\bhonolulu\b', value):
    return "Honolulu"
  elif re.search(r'\b(hono|honu|honna|hono[lu])lulu\b', value):
    return "Honolulu"
  else:
    return value

